async function sendDetailedFirstDailyBrief(request,env,member){
  const p=await preferences(env,member.id)||{};
  if(p.public_daily_brief!==1)return{eligible:false,state:'not-selected',queued:false,sent:false,retry:false};
  const date=iso(env).slice(0,10);
  const idempotencyKey=`daily-control-brief:${member.id}:${date}`;
  const existing=await first(env.MEMBERS_DB.prepare('SELECT id,status,provider_message_id,last_error FROM email_outbox WHERE idempotency_key=? LIMIT 1').bind(idempotencyKey));
  if(existing)return{eligible:true,state:existing.status==='sent'?'already-sent':'already-queued',queued:true,sent:existing.status==='sent',retry:existing.status==='retry',providerMessageId:existing.provider_message_id||null,error:existing.last_error||null};
  try{
    const report=await buildMemberIntelligenceReport(request,env,member,'daily');
    if(report.profile?.deliveryMode==='archive_only')return{eligible:true,state:'archive-only',queued:false,sent:false,retry:false,reportId:report.reportId};
    const preferenceToken=await issueToken(env,member.id,'preferences',{memberId:member.id},365*24*60);
    const unsubscribeToken=await issueToken(env,member.id,'unsubscribe',{memberId:member.id},365*24*60);
    const preferenceUrl=`${origin(request)}/subscriber-dashboard.html?token=${encodeURIComponent(preferenceToken)}`;
    const unsubscribeUrl=`${origin(request)}/api/email/unsubscribe?token=${encodeURIComponent(unsubscribeToken)}`;
    const content=appendMarketingFooter(report.htmlContent,report.textContent,preferenceUrl,unsubscribeUrl);
    const campaign=await createCampaign(env,{kind:'daily',segmentKey:'public_daily_brief',subject:report.emailSubject,preheader:report.emailPreheader,htmlContent:content.htmlContent,textContent:content.textContent,campaignKey:`detailed-first-brief:${member.id}:${date}`,canonicalRecordIds:report.sourceIds,evidenceCheckpointAt:report.sourceCollectionCutoff},'email-verification');
    await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO email_deliveries (id,campaign_id,member_id,recipient_email_hash,status,queued_at,updated_at) VALUES (?,?,?,?, 'queued',?,?)`).bind(id(env,'email-delivery'),campaign.id,member.id,await emailHash(member.email),iso(env),iso(env)).run();
    await enqueue(env,member,{campaignId:campaign.id,messageKind:'daily',subject:report.emailSubject,htmlContent:content.htmlContent,textContent:content.textContent,idempotencyKey});
    await env.MEMBERS_DB.prepare(`UPDATE email_campaigns SET status='sending',started_at=COALESCE(started_at,?),recipient_count=1,updated_at=? WHERE id=?`).bind(iso(env),iso(env),campaign.id).run();
    const delivery=await processOutbox(env,{memberId:member.id,limit:10});
    const state=delivery.sent>0?'sent':delivery.retry>0?'queued-for-retry':delivery.failed>0?'failed':'queued';
    await audit(env,member.id,'email.daily.detailed_first_brief','intelligence_report',report.reportId,{state,version:report.version,unchanged:report.unchanged,...delivery});
    return{eligible:true,state,queued:true,sent:delivery.sent>0,retry:delivery.retry>0,failed:delivery.failed>0,campaignId:campaign.id,reportId:report.reportId,reportVersion:report.version,pdfUrl:report.links?.pdf||null,...delivery};
  }catch(error){
    await audit(env,member.id,'email.daily.detailed_first_brief_fallback','member',member.id,{error:clean(error?.message||error,500)});
    return sendFirstDailyBrief(request,env,member);
  }
}

async function queuePersonalizedAutomatedCampaign(request,env,campaign,kind){
  const content=await first(env.MEMBERS_DB.prepare('SELECT * FROM email_campaign_content_versions WHERE id=?').bind(campaign.content_version_id));
  const segment=await first(env.MEMBERS_DB.prepare('SELECT segment_key FROM email_segments WHERE id=?').bind(campaign.segment_id));
  const recipients=await eligibleMembers(env,segment.segment_key);
  const batchLimit=Math.max(1,Math.min(250,Number(env?.INTELLIGENCE_REPORT_BATCH_LIMIT||100)));
  let queued=0,skippedExisting=0,archiveOnly=0,personalizationFallbacks=0;
  for(const member of recipients){
    if(queued>=batchLimit)break;
    const idempotencyKey=dailyControlBriefIdempotency(campaign,member,env);
    const existing=await first(env.MEMBERS_DB.prepare('SELECT id FROM email_outbox WHERE idempotency_key=? LIMIT 1').bind(idempotencyKey));
    if(existing){skippedExisting+=1;continue}
    let subject=content.subject,htmlContent=content.html_content,textContent=content.text_content,reportId=null;
    try{
      const report=await buildMemberIntelligenceReport(request,env,member,kind);
      reportId=report.reportId;
      if(report.profile?.deliveryMode==='archive_only'){archiveOnly+=1;continue}
      subject=report.emailSubject;htmlContent=report.htmlContent;textContent=report.textContent;
    }catch(error){personalizationFallbacks+=1;await audit(env,member.id,'email.campaign.personalization_fallback','email_campaign',campaign.id,{kind,error:clean(error?.message||error,500)})}
    const preferenceToken=await issueToken(env,member.id,'preferences',{memberId:member.id},365*24*60);
    const unsubscribeToken=await issueToken(env,member.id,'unsubscribe',{memberId:member.id},365*24*60);
    const preferenceUrl=`${origin(request)}/subscriber-dashboard.html?token=${encodeURIComponent(preferenceToken)}`;
    const unsubscribeUrl=`${origin(request)}/api/email/unsubscribe?token=${encodeURIComponent(unsubscribeToken)}`;
    const withFooter=appendMarketingFooter(htmlContent,textContent,preferenceUrl,unsubscribeUrl);
    await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO email_deliveries (id,campaign_id,member_id,recipient_email_hash,status,queued_at,updated_at) VALUES (?,?,?,?, 'queued',?,?)`).bind(id(env,'email-delivery'),campaign.id,member.id,await emailHash(member.email),iso(env),iso(env)).run();
    await enqueue(env,member,{campaignId:campaign.id,messageKind:kind,subject,htmlContent:withFooter.htmlContent,textContent:withFooter.textContent,idempotencyKey,headers:reportId?{'X-Matrix-Report-Id':reportId}:null});
    queued+=1;
  }
  await env.MEMBERS_DB.prepare(`UPDATE email_campaigns SET status=?,started_at=COALESCE(started_at,?),recipient_count=?,updated_at=? WHERE id=?`).bind(queued?'sending':'sent',iso(env),queued,iso(env),campaign.id).run();
  return{recipientCount:queued,skippedExisting,archiveOnly,personalizationFallbacks,batchLimit,remainingEstimate:Math.max(0,recipients.length-skippedExisting-archiveOnly-queued)};
}
async function sendFirstDailyBrief(request,env,member){const p=await preferences(env,member.id)||{};if(p.public_daily_brief!==1)return{eligible:false,state:'not-selected',queued:false,sent:false,retry:false};const date=iso(env).slice(0,10);const idempotencyKey=`daily-control-brief:${member.id}:${date}`;const existing=await first(env.MEMBERS_DB.prepare('SELECT id,status,provider_message_id,last_error FROM email_outbox WHERE idempotency_key=? LIMIT 1').bind(idempotencyKey));if(existing)return{eligible:true,state:existing.status==='sent'?'already-sent':'already-queued',queued:true,sent:existing.status==='sent',retry:existing.status==='retry',providerMessageId:existing.provider_message_id||null,error:existing.last_error||null};const sourceBundle=await loadCampaignSource(request,env,'daily');const items=sourceItems(sourceBundle);const title='Daily Control Brief';const rows=items.length?items.map((item,index)=>({heading:clean(item.title||item.headline||item.subject||item.label||`Signal ${index+1}`,180),summary:clean(item.summary||item.description||item.body||item.finding||'',600)})):[{heading:'Evidence and intelligence update',summary:'The canonical daily source bundle was unavailable, so no unsupported claims were inserted. Open Live Intel for the latest evidence-bounded records.'}];const htmlContent=`<!doctype html><html><body><h1>${html(title)} — ${date}</h1>${rows.map(row=>`<h2>${html(row.heading)}</h2><p>${html(row.summary)}</p>`).join('')}<p><strong>Evidence boundary:</strong> Records and analysis remain subject to their source and interpretive labels. Association is not proof.</p><p><a href="${origin(request)}/live-intel.html">Open Live Intel</a></p></body></html>`;const textLines=[`${title} — ${date}`,''];for(const row of rows){textLines.push(row.heading,row.summary,'')}textLines.push('Evidence boundary: association is not proof.',`${origin(request)}/live-intel.html`);const textContent=textLines.join(String.fromCharCode(10));const campaign=await createCampaign(env,{kind:'daily',segmentKey:'public_daily_brief',subject:`${title} — ${date}`,htmlContent,textContent,campaignKey:`daily-first-brief:${member.id}:${date}`,canonicalRecordIds:items.map(item=>item.canonicalId||item.id).filter(Boolean),evidenceCheckpointAt:clean(sourceBundle?.data?.generatedAt||iso(env),80)},'email-verification');const content=await first(env.MEMBERS_DB.prepare('SELECT * FROM email_campaign_content_versions WHERE id=?').bind(campaign.content_version_id));await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO email_deliveries (id,campaign_id,member_id,recipient_email_hash,status,queued_at,updated_at) VALUES (?,?,?,?, 'queued',?,?)`).bind(id(env,'email-delivery'),campaign.id,member.id,await emailHash(member.email),iso(env),iso(env)).run();await enqueue(env,member,{campaignId:campaign.id,messageKind:'daily',subject:content.subject,htmlContent:content.html_content,textContent:content.text_content,idempotencyKey});await env.MEMBERS_DB.prepare(`UPDATE email_campaigns SET status='sending',started_at=COALESCE(started_at,?),recipient_count=1,updated_at=? WHERE id=?`).bind(iso(env),iso(env),campaign.id).run();const delivery=await processOutbox(env,{memberId:member.id,limit:10});const state=delivery.sent>0?'sent':delivery.retry>0?'queued-for-retry':delivery.failed>0?'failed':'queued';await audit(env,member.id,'email.daily.first_brief','email_campaign',campaign.id,{version:DAILY_FIRST_BRIEF_VERSION,source:sourceBundle?.pathname||null,state,...delivery});return{eligible:true,state,queued:true,sent:delivery.sent>0,retry:delivery.retry>0,failed:delivery.failed>0,campaignId:campaign.id,source:sourceBundle?.pathname||null,...delivery}}
async function handleVerify(request,env){await ensureSchema(env);const url=new URL(request.url);const purpose=clean(url.searchParams.get('purpose')||'verify_marketing',40);if(!['verify_marketing','resubscribe'].includes(purpose))return json({ok:false,error:'Invalid verification purpose'},400);const raw=clean(url.searchParams.get('token'),400);const record=await validToken(env,raw,purpose);const failure=reason=>testMode(env)?json({ok:false,error:reason},400):redirect(`${origin(request)}/email-status.html?error=${encodeURIComponent(reason)}`);if(!record)return failure('expired-or-used');let member=await memberById(env,record.member_id);if(!member)return failure('member-not-found');let scope={};try{scope=JSON.parse(record.scope_json||'{}')}catch{}const stamp=iso(env);await env.MEMBERS_DB.prepare(`UPDATE members SET status='active',marketing_status='subscribed',email_verified_at=COALESCE(email_verified_at,?),updated_at=? WHERE id=?`).bind(stamp,stamp,member.id).run();await markTokenUsed(env,record);if(purpose==='resubscribe')await clearSuppressions(env,member.id,scope.consentId||null);member=await memberById(env,member.id);await savePreferences(env,member.id,{});await syncSegments(env,member);const preferenceToken=await issueToken(env,member.id,'preferences',{memberId:member.id},365*24*60);const unsubscribeToken=await issueToken(env,member.id,'unsubscribe',{memberId:member.id},365*24*60);const providerSync=await syncBrevoContact(env,member,{blacklisted:false});const dashboardUrl=`${origin(request)}/subscriber-dashboard.html?token=${encodeURIComponent(preferenceToken)}`;const unsubscribeUrl=`${origin(request)}/api/email/unsubscribe?token=${encodeURIComponent(unsubscribeToken)}`;const template=await safeWelcomeIntelligenceEmail(request,env,member,{dashboardUrl,unsubscribeUrl});await enqueue(env,member,{messageKind:'welcome',subject:'Welcome to Matrix Reprogrammed',...template,idempotencyKey:`welcome:${member.id}:${stamp.slice(0,10)}`});const welcomeDelivery=await processOutbox(env,{memberId:member.id,limit:5});const firstBrief=await sendFirstDailyBrief(request,env,member);await audit(env,member.id,'email.verified','member',member.id,{purpose,providerSynced:providerSync.synced,welcomeSent:welcomeDelivery.sent>0,firstDailyBrief:firstBrief});if(testMode(env))return json({ok:true,verified:true,memberId:member.id,preferenceToken,unsubscribeToken,dashboardUrl,providerSync,welcomeSent:welcomeDelivery.sent>0,firstDailyBrief:firstBrief});const briefState=encodeURIComponent(firstBrief.state||'not-selected');return redirect(`${origin(request)}/email-status.html?verified=1&token=${encodeURIComponent(preferenceToken)}&dailyBrief=${briefState}`)}

async function preferenceContext(env,raw){const token=await validToken(env,raw,'preferences',{reusable:true});if(!token)return null;const member=await memberById(env,token.member_id);if(!member)return null;const p=await preferences(env,member.id)||await savePreferences(env,member.id,{});const segments=await all(env.MEMBERS_DB.prepare(`SELECT s.segment_key,m.state,m.reason FROM email_segment_memberships m JOIN email_segments s ON s.id=m.segment_id WHERE m.member_id=? ORDER BY s.segment_key`).bind(member.id));return{token,member,preferences:p,segments,suppressed:Boolean(await activeSuppression(env,member.id))}}
async function handlePreferences(request,env){await ensureSchema(env);const url=new URL(request.url);const input=request.method==='POST'?await body(request):{};const raw=clean(input.token||url.searchParams.get('token'),400);const context=await preferenceContext(env,raw);if(!context)return json({ok:false,error:'Invalid or expired preferences token'},401);if(request.method==='GET')return json({ok:true,subscriber:{email:context.member.email,displayName:context.member.display_name,status:context.member.status,marketingStatus:context.member.marketing_status,tier:context.member.tier,verifiedAt:context.member.email_verified_at},preferences:context.preferences,segments:context.segments,suppressed:context.suppressed});const p=await savePreferences(env,context.member.id,input);const member=await memberById(env,context.member.id);await syncSegments(env,member);await audit(env,member.id,'email.preferences.updated','member',member.id,{preferences:p});return json({ok:true,saved:true,preferences:p,segments:await all(env.MEMBERS_DB.prepare(`SELECT s.segment_key,m.state,m.reason FROM email_segment_memberships m JOIN email_segments s ON s.id=m.segment_id WHERE m.member_id=? ORDER BY s.segment_key`).bind(member.id))})}
async function handleSubscriber(request,env){if(request.method!=='GET')return json({ok:false,error:'Method not allowed'},405);return handlePreferences(request,env)}

