function dailyCampaignContent(request,bundle,title,date){const daily=objectValue(bundle.daily);const command=objectValue(bundle.command);const synthesis=objectValue(bundle.synthesis);const actors=actorRows(bundle);const developments=developmentRows(bundle);const sections=sectionRows(bundle);const scenarios=scenarioRows(bundle);const records=recordRows(bundle);const watch=watchRows(bundle);const confidence=objectValue(command.analyticConfidence);const judgement=clean(command.missionConclusion||objectValue(synthesis.evidenceLayer).conclusion||arrayValue(daily.topConclusions)[0]||'The strongest current judgement is the pattern supported by the named records below, not a claim of hidden central command.',1000);const topConclusions=arrayValue(daily.topConclusions).map(item=>clean(item,520)).filter(Boolean).slice(0,5);const sourceLine=bundle.sources.length?bundle.sources.join(', '):'No structured source bundle loaded';const liveUrl=routeUrl(request,'live-intel.html','live-intel.html');const evidenceUrl=routeUrl(request,'evidence-vault.html','evidence-vault.html');const conclusionUrl=routeUrl(request,'conclusion-engine.html','conclusion-engine.html');const entitiesUrl=routeUrl(request,'entity-registry.html','entity-registry.html');const actorHtml=actors.length?actors.map(actor=>{const url=routeUrl(request,actor.route,`search.html?q=${encodeURIComponent(actor.name)}`);return`<div style="border:1px solid #4b3b20;border-radius:12px;padding:14px;margin:10px 0;background:#100d08"><h3 style="margin:0 0 5px;color:#f0ca78"><a href="${html(url)}" style="color:#f0ca78">${html(actor.name)}</a></h3><p style="margin:4px 0"><strong>Documented role:</strong> ${html(actor.role)}</p>${actor.context?`<p style="margin:4px 0;color:#d3c49d"><strong>Why this name matters:</strong> ${html(actor.context)}</p>`:''}</div>`}).join(''):'<p>No named actor had enough structured record support for this edition. The brief does not invent names to fill space.</p>';const developmentHtml=developments.length?developments.map((item,index)=>{const url=routeUrl(request,item.route,'live-intel.html');return`<div style="border-left:3px solid #b5443d;padding:4px 0 4px 14px;margin:15px 0"><p style="margin:0;color:#b9aa82;font-size:12px;text-transform:uppercase">${html(item.lane||'Current record')} · ${html(item.status||'evidence status shown in source')}</p><h3 style="margin:4px 0"><a href="${html(url)}" style="color:#f3e6bd">${index+1}. ${html(item.heading)}</a></h3><p style="margin:5px 0">${html(item.summary||'Open the linked record route for the evidence and limitation.')}</p></div>`}).join(''):'<p>No current development met the publication threshold.</p>';const sectionHtml=sections.length?sections.map(section=>`<div style="border-top:1px solid #3e321d;padding:12px 0"><p style="margin:0;color:#d8b56a;font-size:12px;text-transform:uppercase">${html(section.heading)}</p><h3 style="margin:4px 0">${html(section.headline||section.heading)}</h3><p><strong>What it means:</strong> ${html(section.meaning)}</p>${section.likely?`<p><strong>Likely next:</strong> ${html(section.likely)}</p>`:''}</div>`).join(''):'';const scenarioHtml=scenarios.length?scenarios.map(scenario=>`<div style="border:1px solid #6a2723;border-radius:12px;padding:14px;margin:12px 0;background:#140808"><p style="margin:0;color:#e18c83;font-size:12px;text-transform:uppercase">Speculative scenario · ${html(scenario.band)}</p><h3 style="margin:5px 0">${html(scenario.heading)}</h3><p>${html(scenario.trajectory||'Trajectory not yet described.')}</p><p><strong>What would strengthen it:</strong></p>${bulletHtml(scenario.needed)}<p><strong>What would weaken it:</strong></p>${bulletHtml(scenario.weakens)}${scenario.boundary?`<p style="color:#b9aa82"><strong>Boundary:</strong> ${html(scenario.boundary)}</p>`:''}</div>`).join(''):'<p>No scenario met the structured speculation standard in this edition.</p>';const metrics=`${developments.length} developments · ${actors.length} named actors/institutions · ${scenarios.length} testable scenarios · ${records.length} priority records`;const htmlContent=`<!doctype html><html><body style="margin:0;background:#050505;color:#f3e6bd;font-family:Arial,sans-serif;line-height:1.55"><div style="max-width:760px;margin:auto;padding:28px"><div style="border:1px solid #8d7137;border-radius:18px;padding:28px;background:#0b0905"><p style="margin:0;color:#d8b56a;font-size:12px;letter-spacing:.12em;text-transform:uppercase">Matrix Reprogrammed · ${html(DAILY_CONTROL_BRIEF_VERSION)}</p><h1 style="color:#d8b56a;margin:8px 0">${html(title)} — ${html(date)}</h1><p style="color:#b9aa82">${html(metrics)}</p><div style="border-left:4px solid #d8b56a;padding:12px 16px;background:#151006"><h2 style="margin-top:0">Executive judgement</h2><p>${html(judgement)}</p>${confidence.score!==undefined?`<p><strong>Analytic confidence:</strong> ${html(confidence.score)}/100 · ${html(confidence.band||'')}</p>`:''}<p style="color:#b9aa82">Confidence describes support for the pattern, not the probability of a dramatic event.</p></div><h2 style="color:#d8b56a;margin-top:28px">What changed and why it matters</h2>${developmentHtml}<h2 style="color:#d8b56a;margin-top:28px">Named people and institutions in the record</h2><p style="color:#b9aa82">Names appear only with a documented role or source-linked relationship. Inclusion is not an accusation.</p>${actorHtml}${topConclusions.length?`<h2 style="color:#d8b56a;margin-top:28px">Five evidence-led conclusions</h2>${bulletHtml(topConclusions)}`:''}<h2 style="color:#d8b56a;margin-top:28px">Intelligence lanes</h2>${sectionHtml}<h2 style="color:#d8b56a;margin-top:28px">Speculation desk — testable, not decorative</h2><p>Each scenario must identify what record would strengthen it and what evidence would force a downgrade.</p>${scenarioHtml}<h2 style="color:#d8b56a;margin-top:28px">Records to pull next</h2>${bulletHtml(records)}<h2 style="color:#d8b56a;margin-top:28px">Watch next</h2>${bulletHtml(watch)}<div style="margin-top:28px;padding-top:18px;border-top:1px solid #4b3b20"><p><a href="${html(liveUrl)}" style="color:#f0ca78">Live Intel</a> · <a href="${html(evidenceUrl)}" style="color:#f0ca78">Evidence Vault</a> · <a href="${html(conclusionUrl)}" style="color:#f0ca78">Conclusion Engine</a> · <a href="${html(entitiesUrl)}" style="color:#f0ca78">Entity Registry</a></p><p style="font-size:13px;color:#b9aa82"><strong>Evidence boundary:</strong> Records and analysis remain subject to their source and interpretive labels. Association is not proof. Speculation is not fact. Named roles do not establish guilt, shared motive or central command.</p><p style="font-size:11px;color:#73694f">Structured sources used: ${html(sourceLine)}</p></div></div></div></body></html>`;const textActors=actors.length?actors.map(actor=>`- ${actor.name} — ${actor.role}${actor.context?`\n  Why it matters: ${actor.context}`:''}`).join('\n'):'- No named actor met the structured record threshold.';const textDevelopments=developments.length?developments.map((item,index)=>`${index+1}. ${item.heading}\n   ${item.summary}\n   Status: ${item.status||'See source'}${item.lane?` · Lane: ${item.lane}`:''}`).join('\n\n'):'No current development met the publication threshold.';const textSections=sections.map(section=>`${section.heading}: ${section.headline||section.heading}\nWhat it means: ${section.meaning}${section.likely?`\nLikely next: ${section.likely}`:''}`).join('\n\n');const textScenarios=scenarios.length?scenarios.map(scenario=>`${scenario.heading} [${scenario.band}]\n${scenario.trajectory}\nStrengthen:\n${bulletText(scenario.needed)}\nWeaken:\n${bulletText(scenario.weakens)}${scenario.boundary?`\nBoundary: ${scenario.boundary}`:''}`).join('\n\n'):'No scenario met the structured speculation standard.';const textContent=`${title} — ${date}\n${DAILY_CONTROL_BRIEF_VERSION}\n\n${metrics}\n\nEXECUTIVE JUDGEMENT\n${judgement}${confidence.score!==undefined?`\nAnalytic confidence: ${confidence.score}/100 · ${confidence.band||''}`:''}\nConfidence describes support for the pattern, not event probability.\n\nWHAT CHANGED AND WHY IT MATTERS\n${textDevelopments}\n\nNAMED PEOPLE AND INSTITUTIONS\n${textActors}\n\nFIVE EVIDENCE-LED CONCLUSIONS\n${bulletText(topConclusions)}\n\nINTELLIGENCE LANES\n${textSections}\n\nSPECULATION DESK — TESTABLE, NOT DECORATIVE\n${textScenarios}\n\nRECORDS TO PULL NEXT\n${bulletText(records)}\n\nWATCH NEXT\n${bulletText(watch)}\n\nLive Intel: ${liveUrl}\nEvidence Vault: ${evidenceUrl}\nConclusion Engine: ${conclusionUrl}\nEntity Registry: ${entitiesUrl}\n\nEvidence boundary: Records and analysis remain subject to source and interpretive labels. Association is not proof. Speculation is not fact. Named roles do not establish guilt, shared motive or central command.\n\nStructured sources: ${sourceLine}`;return{htmlContent,textContent,subjectSuffix:developments[0]?.heading||actors[0]?.name||'named records and testable scenarios',canonicalRecordIds:[...developments.map(item=>item.id),...scenarios.map(item=>item.id)].filter(Boolean)}}
async function automatedCampaign(request,env,kind){
  if(!automationEnabled(env))return{enabled:false,created:false,reason:'EMAIL_AUTOMATION_ENABLED is not true'};
  const retryQuarantine=typeof quarantineConfiguredRetries==='function'?await quarantineConfiguredRetries(env,'email-automation'):{configured:false,quarantined:0};
  const source=await loadCampaignSource(request,env,kind);
  const items=sourceItems(source);
  const title=kind==='weekly'?'Weekly Signal Drop':'Daily Control Brief';
  const date=iso(env).slice(0,10);
  const rows=items.length?items.map(campaignRow):[{heading:'No verified source changes loaded',summary:'The source bundle contained no usable records, so the system withheld claims rather than inventing an update.',label:'Fail-closed content boundary',route:'',canonicalId:''}];
  const sourceLabel=source?.pathname||'No source bundle';
  const routeUrl=route=>{if(!route)return'';try{return new URL(route,origin(request)).toString()}catch{return''}};
  const htmlRows=rows.map(row=>`<article style="border-top:1px solid #6f582d;padding:18px 0"><p style="margin:0 0 6px;color:#d8b56a;font-size:12px;text-transform:uppercase;letter-spacing:.08em">${html(row.label)}</p><h2 style="margin:0 0 8px;color:#f3e6bd;font-size:21px">${html(row.heading)}</h2>${row.summary?`<p style="margin:0;color:#e3d7b6;line-height:1.55">${html(row.summary)}</p>`:''}${routeUrl(row.route)?`<p><a href="${html(routeUrl(row.route))}" style="color:#d8b56a">Open the underlying record</a></p>`:''}</article>`).join('');
  const htmlContent=`<!doctype html><html><body style="margin:0;background:#050505;color:#f3e6bd;font-family:Arial,sans-serif"><div style="display:none;max-height:0;overflow:hidden">${html(rows[0]?.heading||title)}</div><div style="max-width:680px;margin:auto;padding:28px"><div style="border:1px solid #8d7137;border-radius:18px;padding:28px;background:#0b0905"><p style="color:#d8b56a;letter-spacing:.12em;text-transform:uppercase;font-size:12px">Matrix Reprogrammed · ${html(date)}</p><h1 style="margin:0 0 12px;color:#d8b56a;font-size:32px">${html(title)}</h1><p style="color:#b9aa82">Source: ${html(sourceLabel)} · ${rows.length} ranked items</p>${htmlRows}<p style="margin-top:24px"><a href="${origin(request)}/daily-brain-brief.html" style="display:inline-block;padding:13px 18px;border-radius:10px;background:#d8b56a;color:#090702;text-decoration:none;font-weight:bold">Open the full intelligence brief</a></p><p style="font-size:13px;color:#b9aa82"><strong>Evidence boundary:</strong> Records and analysis retain their source, status and confidence labels. Association is not proof, and allegations are not findings of guilt.</p></div></div></body></html>`;
  const textContent=`${title} — ${date}\nSource: ${sourceLabel}\n\n${rows.map(row=>`[${row.label}] ${row.heading}\n${row.summary}${routeUrl(row.route)?`\n${routeUrl(row.route)}`:''}`).join('\n\n')}\n\nEvidence boundary: records and analysis retain their source, status and confidence labels. Association is not proof.\n${origin(request)}/daily-brain-brief.html`;
  const campaign=await createCampaign(env,{kind,segmentKey:kind==='weekly'?'public_weekly_digest':'public_daily_brief',subject:`${title} — ${date}`,preheader:rows[0]?.heading||title,htmlContent,textContent,campaignKey:`automation:${kind}:${date}`,canonicalRecordIds:rows.map(row=>row.canonicalId).filter(Boolean),evidenceCheckpointAt:clean(source?.data?.generatedAt||source?.data?.updated||iso(env),80)},'email-automation');
  const queued=await queueCampaign(env,campaign);
  const delivery=await processOutbox(env,{limit:100});
  await audit(env,'email-automation','email.campaign.automated','email_campaign',campaign.id,{kind,source:sourceLabel,retryQuarantine,...queued,...delivery});
  return{enabled:true,created:true,campaignId:campaign.id,source:sourceLabel,retryQuarantine,...queued,...delivery};
}

async function adminHealth(env){await ensureSchema(env);const memberCounts=await all(env.MEMBERS_DB.prepare(`SELECT status,marketing_status,COUNT(*) count FROM members WHERE status<>'deleted' GROUP BY status,marketing_status ORDER BY status,marketing_status`));const outbox=await all(env.MEMBERS_DB.prepare(`SELECT status,COUNT(*) count FROM email_outbox GROUP BY status ORDER BY status`));const campaigns=await all(env.MEMBERS_DB.prepare(`SELECT status,COUNT(*) count FROM email_campaigns GROUP BY status ORDER BY status`));const events=await all(env.MEMBERS_DB.prepare(`SELECT event_type,COUNT(*) count FROM email_events GROUP BY event_type ORDER BY event_type`));const provider=await all(env.MEMBERS_DB.prepare(`SELECT sync_status,COUNT(*) count FROM email_provider_contacts GROUP BY sync_status ORDER BY sync_status`));const senderEmail=clean(env?.MEMBERS_FROM_EMAIL,254);const replyToEmail=clean(env?.MEMBERS_REPLY_TO_EMAIL,254);const configurationReady=providerConfigured(env)&&validEmail(senderEmail)&&validEmail(replyToEmail)&&Boolean(env?.EMAIL_WEBHOOK_SECRET)&&Boolean(env?.ADMIN_API_TOKEN)&&domainAuthenticated(env);return{ok:true,d1Connected:true,schemaReady:true,brevoConfigured:providerConfigured(env),domainAuthenticated:domainAuthenticated(env),transactionalConfigurationReady:configurationReady,transactionalEnabled:transactionalEnabled(env),transactionalLive:configurationReady&&transactionalEnabled(env),automationEnabled:automationEnabled(env),sender:{fromEmailConfigured:validEmail(senderEmail),fromNameConfigured:Boolean(clean(env?.MEMBERS_FROM_NAME,120)),replyToEmailConfigured:validEmail(replyToEmail),replyToNameConfigured:Boolean(clean(env?.MEMBERS_REPLY_TO_NAME,120)),temporaryBrevoDomain:/\.brevosend\.com$/i.test(senderEmail)},memberCounts,outbox,campaigns,events,provider,requiredSecrets:{brevoApiKey:Boolean(env?.BREVO_API_KEY),fromEmail:Boolean(env?.MEMBERS_FROM_EMAIL),fromName:Boolean(env?.MEMBERS_FROM_NAME),replyToEmail:Boolean(env?.MEMBERS_REPLY_TO_EMAIL),replyToName:Boolean(env?.MEMBERS_REPLY_TO_NAME),domainAuthenticated:domainAuthenticated(env),transactionalEnabled:transactionalEnabled(env),webhookSecret:Boolean(env?.EMAIL_WEBHOOK_SECRET),adminToken:Boolean(env?.ADMIN_API_TOKEN)}}}
async function handleAdminSubscriber(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);await ensureSchema(env);const url=new URL(request.url);const requestedEmail=clean(url.searchParams.get('email'),254).toLowerCase();const requestedHash=clean(url.searchParams.get('emailHash'),128);let member=requestedEmail?await memberByEmail(env,requestedEmail):null;if(!member&&requestedHash){const candidates=await all(env.MEMBERS_DB.prepare(`SELECT id,email,display_name,role,tier,status,marketing_status,source,email_verified_at,created_at,updated_at,last_login_at FROM members WHERE status<>'deleted' ORDER BY updated_at DESC LIMIT 500`));for(const candidate of candidates){if(await emailHash(candidate.email)===requestedHash){member=candidate;break}}}if(!member)return json({ok:false,error:'Subscriber not found'},404);const p=await preferences(env,member.id);const segments=await all(env.MEMBERS_DB.prepare(`SELECT s.segment_key,s.label,m.state,m.reason,m.activated_at,m.updated_at FROM email_segment_memberships m JOIN email_segments s ON s.id=m.segment_id WHERE m.member_id=? ORDER BY s.segment_key`).bind(member.id));const suppressions=await all(env.MEMBERS_DB.prepare(`SELECT scope,segment_key,reason,source,active,suppressed_at,cleared_at FROM email_suppressions WHERE member_id=? ORDER BY suppressed_at DESC LIMIT 20`).bind(member.id));const deliveries=await all(env.MEMBERS_DB.prepare(`SELECT c.kind,c.campaign_key,c.status campaign_status,d.status delivery_status,d.provider_message_id,d.queued_at,d.sent_at,d.delivered_at,d.failure_reason FROM email_deliveries d JOIN email_campaigns c ON c.id=d.campaign_id WHERE d.member_id=? ORDER BY d.queued_at DESC LIMIT 30`).bind(member.id));return json({ok:true,subscriber:{id:member.id,emailHash:await emailHash(member.email),displayName:member.display_name,tier:member.tier,status:member.status,marketingStatus:member.marketing_status,verifiedAt:member.email_verified_at,source:member.source},preferences:p,segments,suppressions,deliveries})}
async function handleAdminHealth(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);return json(await adminHealth(env))}
