async function quarantineConfiguredRetries(env,actor='email-automation'){
  const cutoffRaw=clean(env?.EMAIL_RETRY_QUARANTINE_BEFORE||'',80);
  if(!cutoffRaw)return{configured:false,quarantined:0,reason:'EMAIL_RETRY_QUARANTINE_BEFORE is not configured'};
  if(!Number.isFinite(Date.parse(cutoffRaw)))throw new Error('EMAIL_RETRY_QUARANTINE_BEFORE must be a valid ISO time');
  await ensureSchema(env);
  const cutoff=new Date(cutoffRaw).toISOString();
  const rows=await all(env.MEMBERS_DB.prepare(`SELECT id,member_id,campaign_id,message_kind,attempt_count,created_at,last_error FROM email_outbox WHERE status='retry' AND created_at<? ORDER BY created_at`).bind(cutoff));
  const stamp=iso(env);
  const byKind={};
  const campaignIds=new Set();
  for(const row of rows){
    const kind=clean(row.message_kind||'unknown',80)||'unknown';
    byKind[kind]=Number(byKind[kind]||0)+1;
    if(row.campaign_id)campaignIds.add(row.campaign_id);
    const previous=clean(row.last_error||'',300);
    const reason=`Automatically quarantined before newsletter activation at ${stamp}${previous?`: ${previous}`:''}`;
    await env.MEMBERS_DB.prepare(`UPDATE email_outbox SET status='quarantined',locked_at=NULL,last_error=?,updated_at=? WHERE id=? AND status='retry'`).bind(reason,stamp,row.id).run();
    if(row.campaign_id)await env.MEMBERS_DB.prepare(`UPDATE email_deliveries SET status='failed',failed_at=COALESCE(failed_at,?),failure_reason='quarantined-pre-activation-retry',last_event_at=?,updated_at=? WHERE campaign_id=? AND member_id=? AND status IN ('queued','deferred')`).bind(stamp,stamp,stamp,row.campaign_id,row.member_id).run();
  }
  for(const campaignId of campaignIds)await refreshCampaign(env,campaignId);
  if(rows.length)await audit(env,actor,'email.outbox.configured_retries_quarantined','email_outbox','configured-retry-cutoff',{before:cutoff,count:rows.length,byKind,campaignCount:campaignIds.size});
  return{configured:true,quarantined:rows.length,before:cutoff,byKind,campaignsRefreshed:campaignIds.size};
}

async function handleAdminQuarantineRetries(request,env){
  if(!adminAllowed(request,env))return json({ok:false,error:'Forbidden'},403);
  if(automationEnabled(env))return json({ok:false,error:'Disable EMAIL_AUTOMATION_ENABLED before quarantining retries'},409);
  const input=await body(request);
  if(clean(input.confirm||'',80)!=='QUARANTINE_PREACTIVATION_RETRIES')return json({ok:false,error:'Explicit quarantine confirmation is required'},400);
  await ensureSchema(env);
  const requestedCutoff=clean(input.before||iso(env),80);
  if(!Number.isFinite(Date.parse(requestedCutoff)))return json({ok:false,error:'A valid ISO cutoff time is required'},400);
  const cutoff=new Date(requestedCutoff).toISOString();
  const rows=await all(env.MEMBERS_DB.prepare(`SELECT id,member_id,campaign_id,message_kind,attempt_count,created_at,last_error FROM email_outbox WHERE status='retry' AND created_at<? ORDER BY created_at`).bind(cutoff));
  const stamp=iso(env);
  const byKind={};
  const campaignIds=new Set();
  for(const row of rows){
    const kind=clean(row.message_kind||'unknown',80)||'unknown';
    byKind[kind]=Number(byKind[kind]||0)+1;
    if(row.campaign_id)campaignIds.add(row.campaign_id);
    const previous=clean(row.last_error||'',300);
    const reason=`Quarantined before newsletter activation at ${stamp}${previous?`: ${previous}`:''}`;
    await env.MEMBERS_DB.prepare(`UPDATE email_outbox SET status='quarantined',locked_at=NULL,last_error=?,updated_at=? WHERE id=? AND status='retry'`).bind(reason,stamp,row.id).run();
    if(row.campaign_id)await env.MEMBERS_DB.prepare(`UPDATE email_deliveries SET status='failed',failed_at=COALESCE(failed_at,?),failure_reason='quarantined-pre-activation-retry',last_event_at=?,updated_at=? WHERE campaign_id=? AND member_id=? AND status IN ('queued','deferred')`).bind(stamp,stamp,stamp,row.campaign_id,row.member_id).run();
  }
  for(const campaignId of campaignIds)await refreshCampaign(env,campaignId);
  await audit(env,'admin','email.outbox.legacy_retries_quarantined','email_outbox','legacy-retry-batch',{before:cutoff,count:rows.length,byKind,campaignCount:campaignIds.size});
  return json({ok:true,quarantined:rows.length,before:cutoff,byKind,campaignsRefreshed:campaignIds.size,automationEnabled:automationEnabled(env),message:rows.length?'Pre-activation retry messages were quarantined and will not be sent.':'No retry messages matched the cutoff.'});
}
async function fetchHandler(request,env,ctx){try{const path=new URL(request.url).pathname.replace(/\/+$/,'')||'/';if(request.method==='OPTIONS')return new Response(null,{status:204,headers:{...securityHeaders,'Access-Control-Allow-Origin':origin(request),'Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,X-Admin-Token,X-Email-Webhook-Secret'}});if(!emailRoutes.has(path))return json({ok:false,error:'Unknown email lifecycle route'},404);if(!hasD1(env))return json({ok:false,configured:false,error:'MEMBERS_DB is unavailable'},503);if(request.method==='POST'&&['/newsletter-signup','/subscribe-newsletter','/api/membership/signup'].includes(path))return handleSignup(request,env);if(request.method==='GET'&&path==='/api/email/verify')return handleVerify(request,env);if(['GET','POST'].includes(request.method)&&path==='/api/email/preferences')return handlePreferences(request,env);if(request.method==='GET'&&path==='/api/email/subscriber')return handleSubscriber(request,env);if(['GET','POST'].includes(request.method)&&path==='/api/email/unsubscribe')return handleUnsubscribe(request,env);if(request.method==='POST'&&path==='/api/email/resubscribe')return handleResubscribe(request,env);if(request.method==='POST'&&path==='/api/email/provider-webhook')return handleWebhook(request,env);if(request.method==='GET'&&path==='/api/email/admin/health')return handleAdminHealth(request,env);if(request.method==='GET'&&path==='/api/email/admin/subscriber')return handleAdminSubscriber(request,env);if(request.method==='GET'&&path==='/api/email/admin/subscriber')return handleAdminSubscriber(request,env);if(request.method==='GET'&&path==='/api/email/admin/subscriber')return handleAdminSubscriber(request,env);if(request.method==='GET'&&path==='/api/email/admin/subscriber')return handleAdminSubscriber(request,env);if(['GET','POST'].includes(request.method)&&path==='/api/email/admin/campaigns')return handleAdminCampaigns(request,env);if(request.method==='POST'&&path==='/api/email/admin/process-outbox')return handleAdminProcess(request,env);if(request.method==='POST'&&path==='/api/email/admin/run-automation')return handleAdminAutomation(request,env);if(request.method==='POST'&&path==='/api/email/admin/test-transactional')return handleAdminTransactionalTest(request,env);if(request.method==='GET'&&path==='/api/email/admin/report-system-health')return handleAdminReportSystemHealth(request,env);if(request.method==='POST'&&path==='/api/email/admin/quarantine-retries')return handleAdminQuarantineRetries(request,env);return json({ok:false,error:'Method not allowed'},405)}catch(error){return json({ok:false,error:'Email lifecycle failed safely',message:clean(error?.message||error,500)},500)}}
async function scheduledHandler(event,env,ctx){if(!hasD1(env))return;const request=new Request('https://matrixreprogrammed.com/api/email/admin/run-automation');const job=async()=>{await ensureSchema(env);if(!automationEnabled(env))return;if(event?.cron==='15 7 * * 1')await automatedCampaign(request,env,'weekly');else if(event?.cron==='5 6 * * *')await automatedCampaign(request,env,'daily');await processOutbox(env,{limit:250})};if(ctx?.waitUntil)ctx.waitUntil(job());else await job()}

